from sales_dashboard.loader import parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_conversion_rate_counts_none_in_denominator_but_not_as_converted():
    assert conversion_rate([
        {"converted": True}, {"converted": None}, {"converted": False}
    ]) == 1 / 3


def test_empty_conversion_rates():
    assert conversion_rate([]) == 0.0
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_pooled_conversion_rate_weights_every_session_equally():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


def test_conversions_in_window():
    daily_counts = [2, 3, 5]
    assert conversions_in_window(daily_counts, 2) == 8
    assert conversions_in_window(daily_counts, 0) == 0
    assert conversions_in_window(daily_counts, 8) == 10


def test_campaign_summary_rounds_pooled_rate_and_uses_calendar_days():
    groups = {
        "a": parse_session_log(["a,1,1", "b,4,1"]),
        "b": parse_session_log(["c,5,0"]),
        "empty": [],
    }
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "a": [{"converted": True}],
        "b": [{"converted": False}],
    }
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_sorts_keys_and_distinguishes_empty_groups():
    groups = {"z": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_conversion_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 1, 1, 1]) == 3
    assert longest_conversion_streak([0, -1]) == 0
    assert longest_conversion_streak([]) == 0

